    function testOwnerCanSetExcessiveTaxFee() public {
        console.log("--- BEFORE-Trigger Tax state ---");
        uint256 taxFeeBefore = token._taxFee(); // Query current tax fee
        uint256 totalFeesBefore = token.totalFees(); // Query total fees
        console.log("Tax Fee (before): %s", taxFeeBefore);
        console.log("Total Fees (before): %s", totalFeesBefore);

        console.log("--- Trigger: setTaxFeePercent(100) call ---");
